dtsPropsFor.LogEntry:
/** The log row. `type` keys the colour + icon maps (C / ICON). */
entry: {
  /** e.g. "Z2 Aerobic" | "Threshold" | "Upper Strength" | "Cycling". */
  type?: string;
  label?: string;
  /** Short display date, e.g. "6/19". */
  date?: string;
  duration?: string;
  srpe?: number;
  /** PR count — renders the 🏆 badge when set. */
  prs?: number;
  exercises?: Array<{ name?: string; weight?: string; volume?: string; e1rm?: string; pr?: boolean }>;
  coachNote?: string;
  /** "planned" switches the left rail to a dashed accent. */
  status?: string;
  /** Renders the erg metric grid instead of the exercise table. */
  _isErg?: boolean;
  distance_m?: number | null;
  avg_watts?: number | null;
  avg_hr?: number | null;
};
/** Fades the row to 50% opacity. */
done?: boolean;

dtsPropsFor.WorkoutItem:
/** null renders the empty-day placeholder. */
session?: {
  /** Drives the accent colour via workoutAccent(). */
  label?: string;
  done?: boolean;
  /** e.g. "AM" | "PM". */
  slot?: string;
  note?: string;
  fuel?: string;
  meal?: { pre?: string; post?: string };
} | null;
/** Left day rail, e.g. { top: "MON", big: "1", bottom: "wk4" }. */
rail?: { top?: string; big?: string; bottom?: string };
/** Marks today — tints the row and prints "● TODAY". */
highlight?: boolean;
/** @default true */
showRail?: boolean;

dtsPropsFor.WorkoutTarget:
/** Falsy renders the "NO PLANNED SESSION TODAY" placeholder. */
session?: {
  label?: string;
  /** Minutes. */
  duration?: number | string;
  srpe?: number | string;
  notes?: string;
} | null;

dtsPropsFor.LiveMetric:
/** Small uppercase tracked caption above the value. */
label?: string;
/** null or undefined prints "--". */
value?: string | number | null;
/** Optional unit caption below the value. */
unit?: string;
/** Value colour. @default THEME.cyan */
accent?: string;
/** @default "normal" */
size?: 'large' | 'normal' | 'small';
/** Drops the tile to 35% opacity. */
dimmed?: boolean;

dtsPropsFor.ErgTooltip:
/** Supplied by Recharts — true while the tooltip is open. */
active?: boolean;
/** Supplied by Recharts. The hovered datum is `payload[0].payload`. */
payload?: Array<{ payload: Record<string, unknown>; stroke?: string; value?: unknown }>;
/** Supplied by Recharts — the category-axis value for the hovered point. */
label?: string | number;

