dtsPropsFor.PaceTrendChart:
/** Enriched sessions, newest first — reversed internally; entries without pace_500m are dropped. */
data?: Array<{
  /** Seconds per 500m. */
  pace_500m?: number | null;
  pace_500m_str?: string;
  avg_watts?: number | null;
  zone?: string;
  /** Renders a filled dot instead of a hollow ring. */
  hardPush?: boolean;
  date_display?: string;
}>;
/** Zone bands drawn behind the line — build with derivePaceZones(cp). */
paceZones?: Array<{ zone?: string; paceFloor?: number; paceCeil?: number; color?: string }>;
/** @default 180 */
height?: number;
/** @default true */
showBands?: boolean;

